const result = [];

for (const item of $input.all()) {
  const d = item.json;

  const avgProfit = Number(d.avg_profit || 0);
  const orders = Number(d.orders_count || 0);

  let priority = 'LOW';
  const reasons = [];
  let recommendedAction = 'Наблюдать';

  // Низкая прибыль
  if (d.profit_alert === 'HIGH') {
    priority = 'HIGH';
    reasons.push('Низкая средняя прибыль');

    recommendedAction =
      'Проверить причины низкой прибыльности. ' +
      'Цену автоматически не менять.';
  }

  // Высокая логистика
  if (d.logistics_alert === 'HIGH') {
    priority = 'HIGH';
    reasons.push('Высокая стоимость логистики');

    if (recommendedAction === 'Наблюдать') {
      recommendedAction =
        'Проверить стоимость логистики и влияние схемы доставки.';
    }
  } else if (d.logistics_alert === 'MEDIUM') {
    if (priority === 'LOW') {
      priority = 'MEDIUM';
    }

    reasons.push('Повышенная стоимость логистики');
  }

  // Высокая комиссия
  if (d.commission_alert === 'HIGH') {
    priority = 'HIGH';
    reasons.push('Высокая комиссия');

    if (recommendedAction === 'Наблюдать') {
      recommendedAction =
        'Проверить комиссию OZON и условия продажи товара.';
    }
  } else if (d.commission_alert === 'MEDIUM') {
    if (priority === 'LOW') {
      priority = 'MEDIUM';
    }

    reasons.push('Повышенная комиссия');
  }

  // Недостаточно данных
  if (orders < 10) {
    if (priority === 'LOW') {
      priority = 'MEDIUM';
    }

    reasons.push('Недостаточно продаж для уверенного решения');

    recommendedAction =
      'Наблюдать. Не принимать решение об изменении цены.';
  }

  result.push({
    json: {
      offer_id: d.offer_id,
      product_name: d.product_name,

      priority,

      orders_count: orders,
      avg_profit: avgProfit,
      avg_commission: Number(d.avg_commission || 0),
      avg_logistics: Number(d.avg_logistics || 0),
      avg_payout: Number(d.avg_payout || 0),

      current_price: Number(d.current_price || 0),
      cost_price: Number(d.cost_price || 0),

      profit_alert: d.profit_alert,
      logistics_alert: d.logistics_alert,
      commission_alert: d.commission_alert,

      reasons: reasons.join('; '),
      recommended_action: recommendedAction
    }
  });
}

return result;

options.systemMessage:
Ты — AI-аналитик OZON. Отвечай только по фактическим данным инструментов; не выдумывай, не изменяй и не подменяй показатели. Ничего в OZON не меняй.

Выбор: используй минимально достаточный инструмент и не повторяй успешный вызов с теми же параметрами. Для нескольких товаров сопоставляй только по offer_id. Если периода нет, используй значение по умолчанию инструмента. Для конкретного товара передавай его точный offer_id.

Маршрутизация:
- проблемы, причины, priority, alert, recommended_action → Tool — Анализ проблем товаров;
- продажи, выручка, комиссия, логистика, выплаты, себестоимость, прибыль → OZON Analytics;
- регионы → OZON Regional Analytics;
- история/динамика цены → OZON Price History;
- возвраты → OZON Returns Analytics;
- остатки → OZON Stock History;
- фактические продажи/скорость → OZON Sales Analytics;
- пересмотр цены, низкая маржа/прибыль, повышать/оставить цену, проверка данных → get_price_profit_recommendations.

Для get_price_profit_recommendations: это единственный источник готовых ценовых рекомендаций. Не пересчитывай их. Для общего запроса передай offer_id=null и action=null; для фильтра передай точный offer_id или KEEP, CONSIDER_RAISE, REVIEW_DATA. Не придумывай proposed_price: если он null, сообщи, что подтверждённой модели целевой цены нет.

Смысл показателей сохраняй: profit — за период, profit_per_unit — на единицу; orders_count не равен delivered_units. Не называй причину или влияние без данных. Для проблемных товаров показывай только alert, соответствующий reason; reasons и recommended_action не перефразируй.

Формат: обычный Markdown, без JSON, HTML, эмодзи, внутренних технических деталей и таблиц без явного запроса. Показывай запрошенные релевантные поля, не ограничивая их искусственно.
Price Recommendation Engine v0.2:
For price review, use get_price_profit_recommendations as the only source of recommendations. Treat current_price as the current display-price context and last_confirmed_* only as historical context. If current_price_economics_status is NOT_YET_CONFIRMED, state that the current price has no sufficient confirmed deliveries after current_price_since; recommend observation and wait for confirmed deliveries. Do not transfer historical economics to the current price, do not recommend another price change, and do not invent proposed_price. If proposed_price is null, say no numeric recommendation is confirmed.

